//! Compact marketplace/router state used for Seaport/Blur-like selector traffic in Vegeta S3.
use cosmwasm_std::{entry_point,to_json_binary,Addr,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdResult};use cw_storage_plus::{Item,Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{RegisterOrder{order_id:String,maker:String},FulfillOrder{order_id:String},CancelOrder{order_id:String},IncrementCounter{}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{GetOrderStatus{order_id:String},GetCounter{address:String}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct Order{pub maker:Addr,pub active:bool,pub fulfiller:Option<Addr>}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct OrderStatus{pub active:bool,pub fulfilled:bool}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct CounterResponse{pub value:u64}
const ORDERS:Map<&str,Order>=Map::new("orders");const COUNTERS:Map<&str,u64>=Map::new("counters");const TOTAL_FULFILLED:Item<u64>=Item::new("total_fulfilled");
#[derive(Error,Debug,PartialEq)]pub enum ContractError{#[error("{0}")]Std(#[from]cosmwasm_std::StdError),#[error("missing order")]MissingOrder,#[error("unauthorized")]Unauthorized}
#[entry_point]pub fn instantiate(deps:DepsMut,_:Env,_:MessageInfo,_:InstantiateMsg)->Result<Response,ContractError>{TOTAL_FULFILLED.save(deps.storage,&0)?;Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,_:Env,info:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::RegisterOrder{order_id,maker}=>{let maker=deps.api.addr_validate(&maker)?;ORDERS.save(deps.storage,&order_id,&Order{maker,active:true,fulfiller:None})?;Ok(Response::new())},ExecuteMsg::FulfillOrder{order_id}=>{ORDERS.update(deps.storage,&order_id,|x|->Result<_,ContractError>{let mut o=x.ok_or(ContractError::MissingOrder)?;o.active=false;o.fulfiller=Some(info.sender);Ok(o)})?;TOTAL_FULFILLED.update(deps.storage,|x|->StdResult<_>{Ok(x+1)})?;Ok(Response::new())},ExecuteMsg::CancelOrder{order_id}=>{ORDERS.update(deps.storage,&order_id,|x|->Result<_,ContractError>{let mut o=x.ok_or(ContractError::MissingOrder)?;if o.maker!=info.sender{return Err(ContractError::Unauthorized)};o.active=false;Ok(o)})?;Ok(Response::new())},ExecuteMsg::IncrementCounter{}=>{COUNTERS.update(deps.storage,info.sender.as_str(),|x|->StdResult<_>{Ok(x.unwrap_or_default()+1)})?;Ok(Response::new())}}}
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::GetOrderStatus{order_id}=>{let o=ORDERS.may_load(deps.storage,&order_id)?;to_json_binary(&OrderStatus{active:o.as_ref().map(|x|x.active).unwrap_or(false),fulfilled:o.and_then(|x|x.fulfiller).is_some()})},QueryMsg::GetCounter{address}=>to_json_binary(&CounterResponse{value:COUNTERS.may_load(deps.storage,&address)?.unwrap_or_default()})}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn counter_is_sender_keyed_and_order_status_is_order_keyed(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("x",&[]),InstantiateMsg{}).unwrap();execute(d.as_mut(),mock_env(),mock_info("alice",&[]),ExecuteMsg::IncrementCounter{}).unwrap();execute(d.as_mut(),mock_env(),mock_info("alice",&[]),ExecuteMsg::RegisterOrder{order_id:"o1".into(),maker:"alice".into()}).unwrap();execute(d.as_mut(),mock_env(),mock_info("bob",&[]),ExecuteMsg::FulfillOrder{order_id:"o1".into()}).unwrap();assert_eq!(COUNTERS.load(d.as_ref().storage,"alice").unwrap(),1);assert!(!ORDERS.load(d.as_ref().storage,"o1").unwrap().active);}}
